const promptVersion = 'b3-rescue-v1';
// B3 No-Show Rescue — parse AI rescue email
const rawText = $input.item.json['rawAIText'] || '';
const d = $('Edit Fields — Setup').item.json;

const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
}
if (!parsed || !parsed['body']) {
  parsed = {
    subject: 'We missed you today — let\'s find a new time',
    body: 'Hi ' + d['firstName'] + ', we noticed you missed your ' + d['service'] + ' appointment today. No worries at all — life happens. Whenever you\'re ready, we\'d love to see you: ' + d['rebookLink'] + '\n\n' + d['businessName']
  };
}
const parseSuccess = !!parsed['body'] && parsed['subject'] !== 'We missed you today — let\'s find a new time';
return { ...d, promptVersion, subject: parsed['subject'], body: parsed['body'], parseSuccess };

