// B3 v3-003 — Filter bookings needing Touch 2 or Touch 3 (header-whitespace safe)
const trimKeys = (r) => { const out = {}; for (const [k, v] of Object.entries(r || {})) out[k.trim()] = v; return out; };
const rows = $input.all().map(i => trimKeys(i.json));
const setup = $('Edit Fields — Scanner Setup').item.json;
const now = new Date(setup['nowIso']);

const candidates = [];
for (const r of rows) {
  if (!r['Booking ID']) continue;
  if (r['Rebooked'] === 'Yes') continue;
  if (r['Rescue Sent'] !== 'Yes') continue;
  const touchesSent = parseInt(r['Touches Sent'] || '1');
  if (touchesSent >= 3) continue;
  const lastTouchAtStr = r['Last Touch At'] || r['Rescue Sent At'] || r['Created At'];
  if (!lastTouchAtStr) continue;
  const lastTouchAt = new Date(lastTouchAtStr);
  if (isNaN(lastTouchAt.getTime())) continue;
  const daysSinceLastTouch = (now - lastTouchAt) / (1000 * 60 * 60 * 24);
  // Touch 2 fires 3+ days after touch 1; Touch 3 fires 4+ days after touch 2
  const requiredDays = touchesSent === 1 ? 3 : 4;
  if (daysSinceLastTouch < requiredDays) continue;
  // Don't try to touch a >30-day-old failure — graveyard
  if (daysSinceLastTouch > 30) continue;
  candidates.push({
    bookingId: r['Booking ID'],
    customerName: r['Customer Name'] || 'Customer',
    customerEmail: r['Customer Email'] || '',
    firstName: (r['Customer Name'] || 'there').split(' ')[0],
    businessName: r['Business Name'] || 'Your Business',
    service: r['Service'] || 'your appointment',
    appointmentTime: r['Appointment Time'] || '',
    rebookLink: r['Rebook Link'] || 'https://cal.com/seth-mokone-limbt0/30min',
    rescueOriginalAt: r['Rescue Sent At'] || r['Created At'],
    lastTouchAt: lastTouchAtStr,
    daysSinceLastTouch: Math.round(daysSinceLastTouch),
    nextTouch: touchesSent + 1,
    stage: touchesSent + 1,
    scanId: setup['scanId'],
    nowIso: setup['nowIso']
  });
}
return candidates.map(c => ({ json: c }));

