const promptVersion = 'b3-touch-v1';
// B3 v3-002 — Parse Touch AI response (per-item)
const rawText = $input.item.json['rawAIText'] || '';
const d = $('Code — Filter Touch Candidates').item.json;

const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
}

if (!parsed || !parsed['body']) {
  const isStage3 = d['stage'] === 3;
  parsed = {
    subject: isStage3 ? 'One last note from ' + d['businessName'] : 'Still here when you are, ' + d['firstName'],
    body: isStage3
      ? 'Hi ' + d['firstName'] + ", we know you haven't had a chance to rebook yet — totally understand. We'll keep your file open for one more week. If you change your mind, the door is open: " + d['rebookLink'] + '\n\n' + d['businessName']
      : 'Hi ' + d['firstName'] + ", just checking in — your " + d['service'] + " slot is still here for you whenever you are ready: " + d['rebookLink'] + '\n\n' + d['businessName']
  };
}

const parseSuccess = !!parsed['body'] && !!parsed['subject'];
return { ...d, promptVersion, subject: parsed['subject'], body: parsed['body'], parseSuccess };

